(() => {
  const res = [];
  const heads = [...document.querySelectorAll('table.board th')].map(th => th.innerText.split('\n')[0].trim());
  // Kanboard: body row cells in same order as headers
  const cells = [...document.querySelectorAll('#board-container table.board tbody tr td, table.board tbody tr td')];
  cells.forEach((td, i) => {
    const titles = [...td.querySelectorAll('.task-board-title a, a[href*="task_id="]')].map(a => a.innerText.trim()).filter(t => t && !/^\d+$/.test(t));
    res.push({idx: i, head: heads[i] || null, titles: [...new Set(titles)]});
  });
  return {heads, res};
})()

(() => {
  const t = [...document.querySelectorAll('table')].map(tb => ({cls: tb.className, id: tb.id, parentId: tb.parentElement && tb.parentElement.id, parentCls: tb.parentElement && tb.parentElement.className}));
  return {tableCount: t.length, t, bodyHtmlSnippet: document.querySelector('#board-container') ? document.querySelector('#board-container').id : null};
})()

(() => {
  const out = [];
  const heads = [...document.querySelectorAll('#board th')].map(th => th.innerText.replace(/\s+/g,' ').trim());
  const rows = [...document.querySelectorAll('#board tbody tr')];
  rows.forEach((tr, ri) => {
    const tds = [...tr.children];
    const entry = {};
    tds.forEach((td, i) => {
      const titles = [...td.querySelectorAll('a[href*="task_id="]')].map(a => a.innerText.replace(/\s+/g,' ').trim()).filter(t => t && !/^#\d+$/.test(t));
      entry[heads[i] || ('col'+i)] = [...new Set(titles)];
    });
    out.push({row: ri, entry});
  });
  return {heads, out};
})()

(() => {
  const heads = [...document.querySelectorAll('table.board thead th, #board thead th')].map(th => th.innerText.replace(/\s+/g,' ').replace(/Task count.*/,'').trim());
  const rows = [...document.querySelectorAll('table.board tbody tr, #board tbody tr')];
  const out = [];
  rows.forEach(tr => {
    [...tr.children].forEach((td, i) => {
      const cards = [...td.querySelectorAll('.task-board, .board-task-list > div, div[data-task-id]')];
      const info = cards.map(c => {
        const titleEl = c.querySelector('.task-board-title a, a[href*="task_id="]');
        const idEl = c.querySelector('.task-board-id, [class*="task-id"]');
        return {title: titleEl ? titleEl.innerText.trim() : null, href: titleEl ? titleEl.getAttribute('href') : null, idText: idEl ? idEl.innerText.trim() : null, full: c.innerText.replace(/\s+/g,' ').trim().slice(0,120)};
      });
      out.push({col: heads[i] || ('col'+i), cards: info});
    });
  });
  return {heads, out};
})()
